function openIsland(r,selectedEdition=null){
 const out=$('islandDetailContent');out.replaceChildren();const id=r[5]?null:draftIds[r[0]];
 const title=document.createElement('h1');title.textContent=r[0];const geo=document.createElement('p');geo.textContent=r[1]+' · '+r[2];out.append(title,geo,islandDetails(r[0]));
 for(const e of ['N','S']){const cell=document.createElement('article');cell.className='panel';if(id){cell.id='edition-'+id+'-'+e;cell.tabIndex=-1;cell.classList.toggle('selected-edition',selectedEdition===id+'-'+e)}const heading=document.createElement('h2');heading.textContent=e==='N'?'North-Up':'South-Up';cell.append(heading);
 cell.append(editionRecord(Boolean(id)));
 if(id){const img=document.createElement('img');img.src=previewEditions.find(x=>x.id===id+'-'+e).image;img.alt=r[0]+' '+heading.textContent;img.style.width='100%';cell.append(img);const actions=document.createElement('div');actions.className='artwork-actions';actions.append(shareLink(previewEditions.find(x=>x.id===id+'-'+e)));cell.append(actions);const offer=document.createElement('button');offer.disabled=true;offer.textContent='Make an offer · unavailable until collected';cell.append(offer);
 fetch(previewEditions.find(x=>x.id===id+'-'+e).image.replace(/\.png$/,'.json')).then(res=>{if(!res.ok)throw Error();return res.json()}).then(m=>{const t=draftTraits[r[0]],j=e==='N'?0:1;const attributes={'Island ID':id,'Artwork ID':id+'-'+e,'Island':r[0],'Country':r[1],'Region':t[0],'Island Type':t[1],'Water Type':t[2],'Ocean':t[3],'Water Body':t[4],'Largest Settlement':t[9]??null,'Area':m.area_km2==null?null:Number(m.area_km2).toLocaleString('en-US',{maximumFractionDigits:3})+' km²','Scale':m.artwork_print_scale_denominator?'1:'+Math.round(m.artwork_print_scale_denominator).toLocaleString('en-US'):null,'Orientation':heading.textContent,'Color Palette':m.color_mood,'Color Family':t[5+j],'Background':t[7+j]};const dl=document.createElement('dl');dl.className='edition-traits';for(const [k,v] of Object.entries(attributes)){if(v==null)continue;const dt=document.createElement('dt');dt.textContent=k;const dd=document.createElement('dd');dd.textContent=v;dl.append(dt,dd)}cell.append(dl);const note=document.createElement('small');note.textContent='Draft traits · geographic and licensing review pending';cell.append(note)}).catch(()=>{const note=document.createElement('p');note.textContent='Artwork metadata unavailable';cell.append(note)});}

 else{const button=document.createElement('button');button.disabled=true;button.textContent='Reserve · 750,000 $KEY';cell.append(button);const note=document.createElement('p');note.textContent='Outbid step: 50,000 $KEY · one active holder · payments coming soon';cell.append(note);}
 out.append(cell);}show('islandDetail');if(id){const editionId=selectedEdition||id+'-N';history.replaceState(null,'',editionUrl(editionId,location.origin));if(selectedEdition){const target=$('edition-'+selectedEdition);target?.focus({preventScroll:true});target?.scrollIntoView({block:'start'});}}
}
$('backIndex').onclick=()=>show('index');$('indexSearch').oninput=()=>{indexLimit=100;renderIndex()};$('indexSort').onchange=renderIndex;$('indexStatus').onchange=renderIndex;renderIndex();

function rotateIsland(angle){angle=((Number(angle)%360)+360)%360;$('rotation').value=angle;$('islandRotation').style.transform=`rotate(${angle}deg)`;$('northArrow').style.transform=`rotate(${angle}deg)`;$('degrees').textContent=angle+'°';$('orientation').textContent=angle===0?'North up':angle===180?'South up':angle+'° clockwise';} $('rotation').oninput=e=>rotateIsland(e.target.value);$('north').onclick=()=>rotateIsland(0);$('south').onclick=()=>rotateIsland(180);$('resetRotation').onclick=()=>rotateIsland(0);
function show(page){if(page==='index')loadGlobalIslands();if(page!=='islandDetail'&&new URLSearchParams(location.search).has('edition')){const url=new URL(location.href);url.searchParams.delete('edition');history.replaceState(null,'',url);}for(const el of document.querySelectorAll('.page'))el.hidden=el.id!==page;for(const el of document.querySelectorAll('nav button')){el.classList.toggle('active',el.dataset.page===(page==='islandDetail'?'index':page));el.setAttribute('aria-current',el.dataset.page===page?'page':'false')}window.scrollTo(0,0);if(page==='atlas')requestAnimationFrame(()=>worldMap.invalidateSize())}
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>show(el.dataset.page));
function render(){const k=Number($('keysRange').value);$('price').textContent=k+' keys · '+discount(k)+'% off · '+mintPrice('500000',k).toLocaleString('en-US')+' KEY'}$('keysRange').oninput=render;render();
$('paykey').onclick=()=>{$('paykey').classList.add('selected');$('paycheers').classList.remove('selected');$('paymentnote').textContent='Stake Creator Keys to unlock up to 25% off. Your verified discount is not yet available.'};
$('paycheers').onclick=()=>{$('paycheers').classList.add('selected');$('paykey').classList.remove('selected');$('paymentnote').textContent='CHEERS quote unavailable. The displayed 500,000 KEY is the reference price, not a CHEERS quote.'};
$('connect').onclick=async()=>{try{const provider=miniApp?await sdk.wallet.getEthereumProvider():window.ethereum;if(!provider)throw Error('No wallet detected. Use Keys to look up a public address.');const a=await provider.request({method:'eth_requestAccounts'});if(!a[0])throw Error('No account selected');$('wallet').value=a[0];$('connect').textContent=a[0].slice(0,6)+'…'+a[0].slice(-4);$('status').textContent='Wallet connected. No transaction requested.'}catch(e){$('status').textContent=e.message||'Connection cancelled.'}};
async function read(button,out,url,format){button.disabled=true;out.textContent='Loading…';try{const r=await fetch(url);if(!r.ok)throw Error();const p=await r.json();out.replaceChildren();format(p.data,out)}catch{out.textContent='Data unavailable. Try again later.'}finally{button.disabled=false}}
function raw(data,out){const pre=document.createElement('pre');pre.textContent=JSON.stringify(data,null,2);out.append(pre)}
$('holdings').onclick=()=>{const w=$('wallet').value.trim();if(!/^0x[a-fA-F0-9]{40}$/.test(w)){$('positions').textContent='Enter a valid Base wallet address.';return}read($('holdings'),$('positions'),'/api/wallet?wallet='+encodeURIComponent(w),raw)};
$('load').onclick=()=>read($('load'),$('results'),'/api/markets?q='+encodeURIComponent($('search').value),(data,out)=>{for(const item of data?.items??[])raw(item,out);if(!out.children.length)out.textContent='No markets found.'});
let keyQuote=null;function displayUsd(){const fmt=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:4});$('usdquote').textContent=keyQuote===null?'KEY market quote unavailable':'≈ '+fmt(500000*keyQuote)+' USD equivalent · KEY reference price';$('discountusd').textContent=keyQuote===null?'USD estimate unavailable':'≈ '+fmt(Number(mintPrice('500000',Number($('keysRange').value)))*keyQuote)+' USD equivalent · simulated discount';} $('keysRange').addEventListener('input',displayUsd);async function refreshQuote(){try{const r=await fetch('/api/key-price');if(!r.ok)throw Error();const q=await r.json();if(q.token!=='0xb0ca1e094a1779018b194ac6151ece8d6f05db07'||!Number.isFinite(Number(q.priceUsd))||Number(q.priceUsd)<=0)throw Error();keyQuote=Number(q.priceUsd);}catch{keyQuote=null}displayUsd()}refreshQuote();setInterval(refreshQuote,60000);

async function initFarcaster(){try{miniApp=await sdk.isInMiniApp();if(!miniApp)return;await sdk.actions.ready();const context=await sdk.context;const user=context?.user;if(user?.username)$('status').textContent='Farcaster · @'+user.username;const provider=await sdk.wallet.getEthereumProvider();if(provider){const a=await provider.request({method:'eth_accounts'});if(/^0x[a-fA-F0-9]{40}$/.test(a?.[0]??'')){$('wallet').value=a[0];$('connect').textContent=a[0].slice(0,6)+'…'+a[0].slice(-4);}}}catch{ $('status').textContent='Farcaster connection unavailable. Wallet lookup remains available.'; }}initFarcaster();
const galleryQuery=new URLSearchParams(location.search).get('gallery');
if(galleryQuery){$('gallerySearch').value=galleryQuery;renderGallery();}
const requestedEdition=new URLSearchParams(location.search).get('edition');
if(requestedEdition){if(!openEdition(requestedEdition)){show('gallery');$('status').textContent='Artwork edition not found.';}}else if(location.hash==='#index')show('index');else if(location.hash==='#gallery')show('gallery');

function shareLink(edition){
 const link=document.createElement('a');link.href=xShareUrl(edition,location.origin);link.target='_blank';link.rel='noopener noreferrer';link.className='artwork-link share-on-x';link.textContent='Share on X ↗';link.setAttribute('aria-label','Share '+edition.name+' '+edition.orientation+' on X');return link;
}
function editionRecord(artworkExists){
 const state=editionStatus({artworkExists,collectionReleased});
 const record=document.createElement('dl');record.className='edition-record';record.setAttribute('aria-label','Artwork and NFT status');
 for(const [label,key] of [['Artwork','artwork'],['Mint','mint'],['Minted by','mintedBy'],['Owned by','ownedBy']]){
  const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=state[key];
  const address=state[key+'Address'];if(address){dd.title=address;dd.setAttribute('aria-label',address)}
  record.append(dt,dd);
 }
 return record;
}
function openEdition(id){
 const edition=previewEditions.find(e=>e.id===id);if(!edition)return false;
 const row=registry.find(r=>r[0]===edition.name);if(!row)return false;
 openIsland(row,id);return true;
}
